{
  "title": "祠堂的密语",
  "scene": "你站在一座古老的祠堂前，祠堂的木门上雕刻着复杂而古老的图案，似乎与村里的传说有关。祠堂周围是一片寂静，只有远处偶尔传来的鸟鸣声。在门的左边，有一块不起眼的小石碑，上面刻着一行小字：‘欲求真相，必先敬祖’。你想起村民曾提到，祠堂里藏着关于怪谈的线索。",
  "goal": "进入祠堂寻找怪谈的真相",
  "clue": "祠堂门左边的小石碑上刻有关键提示",
  "choices": [
    {
      "id": "A",
      "text": "尝试用力推开祠堂的大门",
      "outcome": "你用力推门，但门纹丝不动，似乎被锁住了。你检查了四周，发现并没有其他入口。好在门上的图案引起了你的兴趣，或许能从中找到线索。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "绕到祠堂后面查看是否有其他入口",
      "outcome": "你绕到祠堂后面，发现了一扇小门。门没有锁，你轻轻一推便开了。你进入祠堂，发现里面堆放着许多古老的祭器，墙上挂着一幅祖先的画像，似乎在对你述说着什么。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "阅读石碑上的文字并轻轻敲击大门",
      "outcome": "你阅读了石碑上的文字，然后轻轻敲击大门。突然，大门缓缓开启，里面传来一阵低沉的钟声。你进入祠堂，发现里面供奉着一尊古老的祖先雕像，墙上挂着一幅详细的族谱图，似乎隐藏着怪谈的秘密。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
